<script setup lang="ts">
import {computed,ref,watch,nextTick} from 'vue'
import {displayColumns,fieldValue,imageValues} from '../../../shared/displayLayout.mjs'
const props=defineProps<{records:any[];manifest:any;catalogRecords?:any[];details?:boolean;selectable?:boolean}>()
const emit=defineEmits<{open:[row:any];selection:[rows:any[]]}>()
const table=ref(),valueOpen=ref(false),expandedValue=ref(''),columns=computed(()=>displayColumns(props.manifest,props.catalogRecords||props.records))
watch(()=>props.records,async()=>{const rows=props.records;await nextTick();if(rows===props.records)table.value?.setScrollTop(0)})
</script>
<template><el-table ref="table" :data="records" stripe height="100%" row-key="id" @selection-change="rows=>emit('selection',rows)" @row-dblclick="row=>details&&emit('open',row)"><el-table-column v-if="selectable" type="selection" width="40" /><el-table-column v-for="column in columns" :key="column.id" :label="column.label" :width="column.key==='main_name'||column.key==='化合物名称'?240:column.group==='source'?360:190" :fixed="column.id==='compound.main_name'||column.key==='化合物名称'?'left':undefined" show-overflow-tooltip><template #default="scope"><el-image v-if="column.key.endsWith('base64')&&imageValues(scope.row,column).length" :src="imageValues(scope.row,column)[0]" :preview-src-list="imageValues(scope.row,column)" lazy fit="contain" style="width:72px;height:50px" preview-teleported /><span v-else class="flat-value" :style="details&&column.key==='main_name'?'cursor:pointer;color:#337ecc':undefined" @click="details&&column.key==='main_name'&&emit('open',scope.row)">{{fieldValue(scope.row,column).toString().slice(0,500)}}<el-button v-if="fieldValue(scope.row,column).toString().length>500" link @click="expandedValue=fieldValue(scope.row,column).toString();valueOpen=true">展开</el-button></span></template></el-table-column><el-table-column v-if="details||$slots.actions" label="操作" width="150"><template #default="scope"><el-button v-if="details" link @click="emit('open',scope.row)">查看</el-button><slot name="actions" :row="scope.row" /></template></el-table-column><template #empty>没有符合条件的记录</template></el-table><el-dialog v-model="valueOpen" title="完整字段内容" append-to-body><pre class="flat-value">{{expandedValue}}</pre></el-dialog></template>
<style scoped>.el-table{flex:1;min-height:0;font-size:13px}.flat-value{white-space:pre-line;overflow-wrap:anywhere}</style>
